export default "[\n  {\n    \"id\": \"BU-mg2.3.1\",\n    \"title\": \"T-0.1: core module and purity gate\",\n    \"description\": \"Phase 0 task T-0.1 of docs/designs/beads-ui-design.md (approved 2026-10-21). Build the DOM-free core module inside the plugin at plugins/beads-ui/core with its purity gate, plus the root monorepo bootstrap it needs (npm workspaces, package-lock.json, turbo.json, biome.json, tsconfig.base.json with the @beads-ui/core path alias).\\n\\nAcceptance criteria (verbatim from the design):\\n- When plugins/beads-ui/core is built, the system shall compile under a tsconfig with \\\"lib\\\": [\\\"es2023\\\"] and \\\"types\\\": [] and shall emit no error.\\n- If any file in plugins/beads-ui/core references setTimeout, setInterval, queueMicrotask, requestAnimationFrame, window, document, process or a Node built-in, then the lint gate shall fail naming the file and line.\\n- When plugins/beads-ui/package.json is read, the system shall find no runtime dependencies.\\n- When claude plugin test runs an import probe, a hooks module importing a core file by relative path and a Client module importing a sibling file shall both load; if either is refused, then the probe shall fail naming the import.\\n\\nDone when: the four ACs hold on beads-ui main, with tests plugins/beads-ui/core/test/purity.test.ts and parsers.test.ts. The import-probe AC needs Claude Code 2.1.299 or later; this host runs 2.1.296.\\n\",\n    \"status\": \"open\",\n    \"priority\": 1,\n    \"issue_type\": \"task\",\n    \"owner\": \"6564880+sergeiwallace@users.noreply.github.com\",\n    \"created_at\": \"2026-10-21T05:48:13Z\",\n    \"created_by\": \"Sergei Wallace\",\n    \"updated_at\": \"2026-10-21T05:48:14Z\",\n    \"metadata\": {\n      \"display_id\": \"BU-t-0-1-core-module-gset\"\n    },\n    \"labels\": [\n      \"id:BU-t-0-1-core-module-gset\"\n    ],\n    \"dependencies\": [\n      {\n        \"id\": \"BU-mg2.3\",\n        \"title\": \"beads-ui Claude Code mod: the task manager inside the Claude Code TUI, with mouse control\",\n        \"description\": \"The first surface and the first MVP target: board, backlog, sprint and roadmap views inside the Claude Code TUI as a Claude Code mod, with mouse drag and drop, plus create, update and delete. Scope and phases come from the beads-ui design doc.\",\n        \"status\": \"in_progress\",\n        \"priority\": 1,\n        \"issue_type\": \"epic\",\n        \"owner\": \"6564880+sergeiwallace@users.noreply.github.com\",\n        \"created_at\": \"2026-10-14T23:31:37Z\",\n        \"created_by\": \"Sergei Wallace\",\n        \"updated_at\": \"2026-10-21T05:48:55Z\",\n        \"started_at\": \"2026-10-21T05:48:55Z\",\n        \"metadata\": {\n          \"display_id\": \"BU-beads-ui-claude-code-aeyb\"\n        },\n        \"labels\": [\n          \"id:BU-beads-ui-claude-code-aeyb\"\n        ],\n        \"dependency_type\": \"parent-child\"\n      }\n    ],\n    \"parent\": \"BU-mg2.3\",\n    \"dependent_count\": 0,\n    \"dependency_count\": 1,\n    \"comment_count\": 0,\n    \"revision\": \"2762705997593229931\"\n  },\n  {\n    \"id\": \"BU-mg2.3.6\",\n    \"title\": \"T-1.2: Backlog tab with sort and filter\",\n    \"description\": \"Phase 1 (MVP) task T-1.2 of docs/designs/beads-ui-design.md (approved 2026-10-21). The Backlog tab of the /beads pane. Founding ask names \\\"sort\\\" and \\\"backlog\\\".\\n\\nAcceptance criteria (verbatim from the design):\\n- When the Backlog tab renders, the system shall list open issues sorted by priority then created date and shall honour the filter expression's type, label, assignee and ready predicates.\\n- When the user enters a filter with an unknown key, the system shall show the accepted keys and shall not change the list.\\n\\nDone when: both ACs hold on beads-ui main with tests (core/test/sort, filter, views).\\n\",\n    \"status\": \"open\",\n    \"priority\": 1,\n    \"issue_type\": \"task\",\n    \"owner\": \"6564880+sergeiwallace@users.noreply.github.com\",\n    \"created_at\": \"2026-10-21T05:48:42Z\",\n    \"created_by\": \"Sergei Wallace\",\n    \"updated_at\": \"2026-10-21T05:48:42Z\",\n    \"metadata\": {\n      \"display_id\": \"BU-t-1-2-backlog-tab-vptb\"\n    },\n    \"labels\": [\n      \"id:BU-t-1-2-backlog-tab-vptb\"\n    ],\n    \"dependencies\": [\n      {\n        \"id\": \"BU-mg2.3\",\n        \"title\": \"beads-ui Claude Code mod: the task manager inside the Claude Code TUI, with mouse control\",\n        \"description\": \"The first surface and the first MVP target: board, backlog, sprint and roadmap views inside the Claude Code TUI as a Claude Code mod, with mouse drag and drop, plus create, update and delete. Scope and phases come from the beads-ui design doc.\",\n        \"status\": \"in_progress\",\n        \"priority\": 1,\n        \"issue_type\": \"epic\",\n        \"owner\": \"6564880+sergeiwallace@users.noreply.github.com\",\n        \"created_at\": \"2026-10-14T23:31:37Z\",\n        \"created_by\": \"Sergei Wallace\",\n        \"updated_at\": \"2026-10-21T05:48:55Z\",\n        \"started_at\": \"2026-10-21T05:48:55Z\",\n        \"metadata\": {\n          \"display_id\": \"BU-beads-ui-claude-code-aeyb\"\n        },\n        \"labels\": [\n          \"id:BU-beads-ui-claude-code-aeyb\"\n        ],\n        \"dependency_type\": \"parent-child\"\n      }\n    ],\n    \"parent\": \"BU-mg2.3\",\n    \"dependent_count\": 0,\n    \"dependency_count\": 1,\n    \"comment_count\": 0,\n    \"revision\": \"4376643917792077566\"\n  },\n  {\n    \"id\": \"BU-mg2.3\",\n    \"title\": \"beads-ui Claude Code mod: the task manager inside the Claude Code TUI, with mouse control\",\n    \"description\": \"The first surface and the first MVP target: board, backlog, sprint and roadmap views inside the Claude Code TUI as a Claude Code mod, with mouse drag and drop, plus create, update and delete. Scope and phases come from the beads-ui design doc.\",\n    \"status\": \"in_progress\",\n    \"priority\": 1,\n    \"issue_type\": \"epic\",\n    \"owner\": \"6564880+sergeiwallace@users.noreply.github.com\",\n    \"created_at\": \"2026-10-14T23:31:37Z\",\n    \"created_by\": \"Sergei Wallace\",\n    \"updated_at\": \"2026-10-21T05:48:55Z\",\n    \"started_at\": \"2026-10-21T05:48:55Z\",\n    \"metadata\": {\n      \"display_id\": \"BU-beads-ui-claude-code-aeyb\"\n    },\n    \"labels\": [\n      \"id:BU-beads-ui-claude-code-aeyb\"\n    ],\n    \"dependencies\": [\n      {\n        \"id\": \"BU-mg2\",\n        \"title\": \"EPIC beads-ui: Beads task manager for the Claude Code TUI, an MCP UI app and a web app, sharing one core\",\n        \"description\": \"Sergei, 2026-10-14 (verbatim record: ai-harness docs/handoffs/2026-10-14-owner-prompt-claude-code-mods-beads-view-doc-view.md). A Jira-like task manager for Beads: kanban board, sprints, backlog, timeline and roadmap, drag to move, reorder and sort, create, update and delete tasks (delete behind an are-you-sure step), sprint burndown and productivity analytics and dashboards, and a view of every Claude Code session's assigned, in-progress and done tasks. Inspiration from Jira, Linear, Todoist, Asana and others.\\n\\nShape (Sergei, 2026-10-14): one public monorepo, beads-ui, for three surfaces that share a core: the Claude Code mod (TUI, mouse control), an MCP UI app for Claude Desktop and Claude web, and a local or hostable web app with infra-as-config templates and quick starts. A mod's drawing surface has no DOM, so the mod shares the data layer, state, layout and theme, not the React components. Mobile (iOS, then Android) and native desktop (macOS, then Linux, then Windows) are later sub-epics, possibly separate repos (beads-mobile, beads-ui-desktop or per-OS) if they cannot reuse the web app.\\n\\nEnd state for the fleet: beads-ui replaces the Claude Code task panel. It is tested and refined in ai-harness, the panel data is backed up, and the panel is disabled per machine profile by a config setting.\\n\\nProcess: /delegate fable /orchestrate /auto-flow. The coordinator runs /orchestrate /research-doc, then the /doc --kind design stage (PRD specs, ACs, diagrams, mockups, decisions, open questions, phased tasks starting with an MVP), then stops for Sergei's review. Design decisions go through /decision-framework; open questions go to /delegate opus spikes or research first.\\n\\nPublic and open source: nothing secret or sensitive in this repo. The Beads store, its ids and private repo names may be committed (Sergei, 2026-10-14).\",\n        \"status\": \"in_progress\",\n        \"priority\": 1,\n        \"issue_type\": \"epic\",\n        \"assignee\": \"aih-ec2-3\",\n        \"owner\": \"6564880+sergeiwallace@users.noreply.github.com\",\n        \"created_at\": \"2026-10-14T23:31:32Z\",\n        \"created_by\": \"Sergei Wallace\",\n        \"updated_at\": \"2026-10-15T23:12:01Z\",\n        \"started_at\": \"2026-10-14T23:32:01Z\",\n        \"metadata\": {\n          \"display_id\": \"BU-epic-beads-ui-beads-task-manager-mg2\"\n        },\n        \"labels\": [\n          \"id:BU-epic-beads-ui-beads-task-manager-mg2\"\n        ],\n        \"dependency_type\": \"parent-child\"\n      }\n    ],\n    \"parent\": \"BU-mg2\",\n    \"dependent_count\": 10,\n    \"dependency_count\": 1,\n    \"comment_count\": 0,\n    \"revision\": \"-4177459428636158178\"\n  },\n  {\n    \"id\": \"BU-mg2\",\n    \"title\": \"EPIC beads-ui: Beads task manager for the Claude Code TUI, an MCP UI app and a web app, sharing one core\",\n    \"description\": \"Sergei, 2026-10-14 (verbatim record: ai-harness docs/handoffs/2026-10-14-owner-prompt-claude-code-mods-beads-view-doc-view.md). A Jira-like task manager for Beads: kanban board, sprints, backlog, timeline and roadmap, drag to move, reorder and sort, create, update and delete tasks (delete behind an are-you-sure step), sprint burndown and productivity analytics and dashboards, and a view of every Claude Code session's assigned, in-progress and done tasks. Inspiration from Jira, Linear, Todoist, Asana and others.\\n\\nShape (Sergei, 2026-10-14): one public monorepo, beads-ui, for three surfaces that share a core: the Claude Code mod (TUI, mouse control), an MCP UI app for Claude Desktop and Claude web, and a local or hostable web app with infra-as-config templates and quick starts. A mod's drawing surface has no DOM, so the mod shares the data layer, state, layout and theme, not the React components. Mobile (iOS, then Android) and native desktop (macOS, then Linux, then Windows) are later sub-epics, possibly separate repos (beads-mobile, beads-ui-desktop or per-OS) if they cannot reuse the web app.\\n\\nEnd state for the fleet: beads-ui replaces the Claude Code task panel. It is tested and refined in ai-harness, the panel data is backed up, and the panel is disabled per machine profile by a config setting.\\n\\nProcess: /delegate fable /orchestrate /auto-flow. The coordinator runs /orchestrate /research-doc, then the /doc --kind design stage (PRD specs, ACs, diagrams, mockups, decisions, open questions, phased tasks starting with an MVP), then stops for Sergei's review. Design decisions go through /decision-framework; open questions go to /delegate opus spikes or research first.\\n\\nPublic and open source: nothing secret or sensitive in this repo. The Beads store, its ids and private repo names may be committed (Sergei, 2026-10-14).\",\n    \"status\": \"in_progress\",\n    \"priority\": 1,\n    \"issue_type\": \"epic\",\n    \"assignee\": \"aih-ec2-3\",\n    \"owner\": \"6564880+sergeiwallace@users.noreply.github.com\",\n    \"created_at\": \"2026-10-14T23:31:32Z\",\n    \"created_by\": \"Sergei Wallace\",\n    \"updated_at\": \"2026-10-15T23:12:01Z\",\n    \"started_at\": \"2026-10-14T23:32:01Z\",\n    \"metadata\": {\n      \"display_id\": \"BU-epic-beads-ui-beads-task-manager-mg2\"\n    },\n    \"labels\": [\n      \"id:BU-epic-beads-ui-beads-task-manager-mg2\"\n    ],\n    \"dependent_count\": 13,\n    \"dependency_count\": 0,\n    \"comment_count\": 9,\n    \"comments_omitted\": true,\n    \"revision\": \"-2235186017900826949\"\n  },\n  {\n    \"id\": \"BU-2zw\",\n    \"title\": \"npm audit: 10 dev-only advisories under markdownlint-cli2\",\n    \"description\": \"`npm audit` on the beads-ui root reports 10 advisories (3 low, 7 high), all in the dev-only dependency tree of `markdownlint-cli2` (braces, js-yaml, katex, markdown-it), measured 2026-10-21 on branch wt/aih-ec2-3/BU-t-0-1-core-module-gset at 588d3ec.\\n\\nThey predate the T-0.1 bootstrap: `markdownlint-cli2 ^0.21.0` was the root package.json's only devDependency at a9e6e45, and `npm ls` traces every flagged package to it. Bumping to the latest `markdownlint-cli2` (0.23.3) still reports 10 advisories, and the braces advisory lists every version as affected, so there is no upgrade that clears them.\\n\\nAll are denial-of-service class advisories in a local lint tool that never ships in the plugin (plugins/beads-ui has no dependencies). Options: npm `overrides` pinning patched js-yaml and markdown-it versions where they exist, dropping the npm copy in favour of the pre-commit hook's own markdownlint-cli2, or accepting them until upstream ships fixes.\\n\\nDone when: the chosen option is applied and `npm audit` reports no high advisory, or the acceptance is recorded with its reason.\\n\",\n    \"status\": \"open\",\n    \"priority\": 3,\n    \"issue_type\": \"bug\",\n    \"owner\": \"6564880+sergeiwallace@users.noreply.github.com\",\n    \"created_at\": \"2026-10-21T06:04:41Z\",\n    \"created_by\": \"Sergei Wallace\",\n    \"updated_at\": \"2026-10-21T06:04:41Z\",\n    \"metadata\": {\n      \"display_id\": \"BU-npm-audit-10-dev-only-advisories-2zw\"\n    },\n    \"labels\": [\n      \"id:BU-npm-audit-10-dev-only-advisories-2zw\"\n    ],\n    \"dependent_count\": 0,\n    \"dependency_count\": 0,\n    \"comment_count\": 0,\n    \"revision\": \"8818105012573493261\"\n  }\n]\n";
